def element_order(g, op, e):
    x, k = g, 1
    while x != e:
        x = op(x, g)
        k += 1
        if k > 10000:
            raise ValueError('no power reaches e')
    return k


def generators(n):
    add = lambda a, b: (a + b) % n
    return [g for g in range(n) if element_order(g, add, 0) == n]
